export async function searchMetadata(query,signal){const u=new URL('https://openlibrary.org/search.json');u.searchParams.set('q',query);u.searchParams.set('limit','8');const r=await fetch(u,{signal});if(!r.ok)throw Error('Сервіс повернув помилку '+r.status);const d=await r.json();return (d.docs||[]).map(x=>({title:x.title||'',authors:(x.author_name||[]).join(', '),year:x.first_publish_year||'',key:x.key}));}
